library ieee;use ieee.std_logic_1164.all;use ieee.numeric_std.all;
entity tb_program_counter_basic is end;architecture tb of tb_program_counter_basic is signal clk:std_logic:='0';signal rst_n:std_logic:='0';signal pc,nxt:std_logic_vector(31 downto 0);signal valid:std_logic;begin clk<=not clk after 5 ns;dut:entity work.program_counter_basic port map(clk_i=>clk,rst_ni=>rst_n,pc_o=>pc,pc_next_o=>nxt,valid_o=>valid);process begin wait for 12 ns;rst_n<='1';wait until rising_edge(clk);wait for 1 ns;assert unsigned(pc)=4 severity error;wait until rising_edge(clk);wait for 1 ns;assert unsigned(pc)=8 severity error;report "PASS" severity note;wait;end process;end;
